  const wkStart = d => C.addDays(d, -C.dow(d));
  const examOpts = () => db().exams.filter(x => S.examStatus(x) !== 'Upcoming').map(x => [x.id, x.name]);
  const defEx = () => (examOpts().slice(-1)[0] || [''])[0];
