    att_student: { t: 'Student attendance', d: 'Attendance percentage by student.', fl: ['g', 'sec', 'q'], def: () => ({}), run(f) { const rs = db().students.filter(s => sOk(s, f) && (!f.q || s.name.toLowerCase().includes(f.q.toLowerCase()))).map(s => ({ s, a: S.studentAtt(s.id) })).sort((a, b) => a.a.pct - b.a.pct); return { cols: ['Student', 'Class', 'Present', 'Absent', 'Late', 'Leave', 'Days', 'Attendance %'], rows: rs.map(x => [x.s.name, S.className(x.s.classId), x.a.P, x.a.A, x.a.L, x.a.V, x.a.total, x.a.pct + '%']) }; } },
